    assert repr(v) == "Vector(1, 2)", f"repr is {v!r}"

@test("addition, subtraction and negation")
def _():
    assert Vector(1, 2) + Vector(3, 4) == Vector(4, 6)
    assert Vector(1, 2) - Vector(3, 4) == Vector(-2, -2)
    assert -Vector(1, -2) == Vector(-1, 2)

@test("scalar multiplication works on both sides")
def _():
    assert Vector(1, 2) * 3 == Vector(3, 6)
    assert 3 * Vector(1, 2) == Vector(3, 6), "3 * v failed: do you have __rmul__?"

@test("abs is the length, bool is false only for zero")
def _():
    assert math.isclose(abs(Vector(3, 4)), 5.0)
    assert not Vector(0, 0)
    assert Vector(0, 1)

@test("equal vectors hash equally (sets and dict keys)")
def _():
    assert len({Vector(1, 2), Vector(1, 2), Vector(2, 1)}) == 2
    d = {Vector(1, 2): "a"}
    assert d[Vector(1, 2)] == "a"
    assert Vector(1, 2) != (1, 2), "a Vector shouldn't equal a tuple"

@test("vectors are immutable")
def _():
    v = Vector(1, 2)
    raises(AttributeError, setattr, v, "x", 10)
    assert v.x == 1

@test("unsupported operands raise TypeError")
def _():
    raises(TypeError, lambda: Vector(1, 2) + 1)
    raises(TypeError, lambda: Vector(1, 2) * "a")
    raises(TypeError, lambda: "a" * Vector(1, 2))

@test("unpacking")
def _():
    x, y = Vector(5, 6)
    assert (x, y) == (5, 6)

reference_solution:
import math


class Vector:
    __slots__ = ("_x", "_y")  # no per-instance __dict__, so no stray attributes either

    def __init__(self, x, y):
        self._x = x
        self._y = y

    @property
    def x(self):
        return self._x

    @property
    def y(self):
        return self._y

    def __add__(self, other):
        if not isinstance(other, Vector):
            return NotImplemented
        return Vector(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        if not isinstance(other, Vector):
            return NotImplemented
        return Vector(self.x - other.x, self.y - other.y)

    def __mul__(self, k):
        if not isinstance(k, (int, float)):
            return NotImplemented
        return Vector(self.x * k, self.y * k)

    __rmul__ = __mul__  # 3 * v: int.__mul__ gives up, so Python tries v.__rmul__(3)

    def __neg__(self):
        return Vector(-self.x, -self.y)

    def __abs__(self):
        return math.hypot(self.x, self.y)

    def __bool__(self):
        return bool(self.x or self.y)

    def __eq__(self, other):
        if not isinstance(other, Vector):
            return NotImplemented
        return (self.x, self.y) == (other.x, other.y)

    def __hash__(self):
        return hash((self.x, self.y))

    def __iter__(self):
        yield self.x
        yield self.y

    def __repr__(self):
        return f"Vector({self.x!r}, {self.y!r})"
